mapper.select:
SELECT k.id, k.category_id, k.keyword, k.weight, k.status,
       c.primary_category, c.sub_label
FROM classify_keyword k
JOIN classify_category c ON c.id = k.category_id

    AND k.category_id = #{categoryId}
    AND k.keyword LIKE CONCAT('%', #{keyword}, '%')
    AND k.status = #{status}

ORDER BY c.primary_category, k.weight DESC, k.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM classify_keyword k

    AND k.category_id = #{categoryId}
    AND k.keyword LIKE CONCAT('%', #{keyword}, '%')
    AND k.status = #{status}

mapper.update:
UPDATE classify_keyword
SET category_id = #{categoryId}, keyword = #{keyword}, weight = #{weight}, status = #{status}
WHERE id = #{id}
